templates.code:
docker ps -a --filter name={nombre}
docker logs -f {nombre}
docker exec -it {nombre} {programa}
docker stop {nombre} && docker rm {nombre}

docker network create {red}
docker run -d --name {nombre} --network {red} {imagen}
# otro contenedor de la red lo encuentra como http://{nombre}:{puerto_cont}

{dependencia}:
  image: {imagen}
  healthcheck:
    test: ["CMD", "curl", "-fsS", "{url_salud}"]
    interval: {intervalo}
    retries: {reintentos}
    start_period: {arranque}

docker compose up --build -d
docker compose logs -f {servicio}
docker compose exec {servicio} {comando}
docker compose down
